from pathlib import Path
import re, shutil, subprocess, base64

ROOT=Path(".")
DOCS=ROOT/"docs"
css_path=DOCS/"site-shell.css"
app_path=DOCS/"app.js"

if not css_path.exists():
    raise SystemExit("docs/site-shell.css nicht gefunden.")

backup=ROOT/"_backup_before_background_cleanup_v2e"
if backup.exists():
    shutil.rmtree(backup)
backup.mkdir(parents=True)

for p in [css_path, app_path]:
    if p.exists():
        dst=backup/p.relative_to(ROOT)
        dst.parent.mkdir(parents=True,exist_ok=True)
        shutil.copy2(p,dst)

assets=DOCS/"assets"
assets.mkdir(parents=True,exist_ok=True)
creator_path=assets/"created-by-xd13.png"
if creator_path.exists():
    creator_backup = backup / "docs/assets/created-by-xd13.png"
    creator_backup.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(creator_path, creator_backup)

creator_path.write_bytes(base64.b64decode(""))

css=css_path.read_text(encoding="utf-8")

# Alte vollständige body.has-site-shell::before/after Blöcke entfernen.
# Nicht nur den letzten Override, sondern alle historischen Varianten.
selectors = [
    r'body\.has-site-shell::before\s*\{[^{}]*\}',
    r'body\.has-site-shell::after\s*\{[^{}]*\}',
]
for pattern in selectors:
    css=re.sub(pattern, "", css, flags=re.S)

# Alte Mobile-Blöcke können nach Entfernen der Selector-Regeln leere @media-Blöcke hinterlassen.
# Nur vollständig leere Media-Blöcke entfernen.
css=re.sub(r'@media\s*\([^)]*\)\s*\{\s*\}', "", css, flags=re.S)

# Frühere Cleanup-v2e Version entfernen, falls Patch erneut ausgeführt wird.
marker="/* === Website background cleanup v2e === */"
if marker in css:
    css=css.split(marker,1)[0].rstrip()+"\n"

css += base64.b64decode("").decode("utf-8")
css_path.write_text(css,encoding="utf-8")

# Sicherheitsprüfung: außerhalb unseres Mobile-Overrides darf es nur je eine Hauptdefinition geben.
css_check=css_path.read_text(encoding="utf-8")

before_count=len(re.findall(r'body\.has-site-shell::before\s*\{',css_check))
after_count=len(re.findall(r'body\.has-site-shell::after\s*\{',css_check))

# before = 2 ist korrekt: Hauptdefinition + genau ein Mobile-Override
if before_count != 2:
    raise RuntimeError(f"Unerwartete Anzahl body.has-site-shell::before: {before_count}")
# after = 1 ist korrekt
if after_count != 1:
    raise RuntimeError(f"Unerwartete Anzahl body.has-site-shell::after: {after_count}")

for needle in [
    'background:url("ally/Ally_main.png")',
    'opacity:.30',
    'background:rgba(3,8,15,.40)',
    'opacity:.25',
]:
    if needle not in css_check:
        raise RuntimeError("CSS-Prüfung fehlgeschlagen: "+needle)

if not creator_path.exists():
    raise RuntimeError("Created-by-Bild wurde nicht geschrieben.")

node=shutil.which("node")
if node and app_path.exists():
    result=subprocess.run([node,"--check",str(app_path)],capture_output=True,text=True)
    if result.returncode!=0:
        raise RuntimeError("JavaScript-Syntaxfehler:\n"+result.stderr)

print("OK: Website-Background-Cleanup v2e angewendet.")
print("- alte ::before/::after Altlasten entfernt")
print("- genau eine Haupt-Hintergrunddefinition")
print("- ein Mobile-Override")
print("- neues transparentes XD13 Created-by-Bild übernommen")
print(f"::before Definitionen: {before_count} (1 Haupt + 1 Mobile)")
print(f"::after Definitionen: {after_count}")
print("Backup:",backup)
